mapper.select:
SELECT GROUPCD, GROUPNAME, COMCD, COMNAME, ACCTGRPCD, ACCTGRPNM, ACCTCD, ACCTNM, SYS, get_date_fmt(PRDATETIME) PRDATE, CHK, INOUT FROM ACCT_TB WHERE CHK = 'Y' AND GROUPCD = #{USER.GROUPCD} AND COMCD = #{USER.COMCD}
AND CHK = 'Y'
AND CHK = 'N'
AND INOUT = #{frmINOUT}
AND ACCTNM LIKE '%' + #{frmACCTNAME} + '%'
ORDER BY GROUPCD ASC,COMCD ASC,INOUT,ACCTNM

mapper.insert:
 
	  
	  	SELECT ISNULL(MAX(CONVERT(INT,ACCTCD)),0) + 1 ACCTCD FROM ACCT_TB WHERE COMCD = #{USER.COMCD}
	  
	  	
		INSERT INTO ACCT_TB (
		  		 GROUPCD   
		         ,GROUPNAME   
		         ,COMCD   
		         ,COMNAME
		         ,ACCTGRPCD   
		         ,ACCTGRPNM   
		         ,ACCTCD   
		         ,ACCTNM   
		         ,SYS   
		         ,INOUT 		
		         ,PRDATETIME
		         ,PRUSERID
		         ,CHK   
		)
		SELECT 
		  		#{USER.GROUPCD}   
		        ,#{USER.GROUPNAME}   
		        ,#{USER.COMCD}   
		        ,#{USER.COMNAME}   
		        ,''   
		        ,#{ACCTGRPNM}
		        ,#{ACCTCD}
		        ,#{ACCTNM}
		        ,'N'
		        ,#{INOUT}
		        ,DATEFORMAT(GETDATE(),'YYYYMMDDHHNNSS')
		        ,#{USER.USERID}
		        ,'Y'
		FROM DUMMY 
		WHERE NOT EXISTS (SELECT 1 FROM ACCT_TB C WHERE C.COMCD = #{USER.COMCD} AND ACCTCD = #{ACCTCD} )

mapper.update:
 
		UPDATE ACCT_TB SET
				ACCTGRPNM = #{ACCTGRPNM}
				,ACCTNM = #{ACCTNM}
				,INOUT = #{INOUT}
				,EDITUSERID = #{USER.USERID}
				,EDITDATETIME = DATEFORMAT(GETDATE(),'YYYYMMDDHHNNSS')
		WHERE ACCTCD = #{ACCTCD} AND COMCD = #{COMCD}

 
		UPDATE ACCT_TB SET
				CHK = 'N'
				,EDITUSERID = #{USER.USERID}
				,EDITDATETIME = DATEFORMAT(GETDATE(),'YYYYMMDDHHNNSS')
		WHERE ACCTCD = #{ACCTCD} AND COMCD = #{COMCD}
